#include <stdio.h>
int main(void){int m; printf("Enter month number (1-12): "); scanf("%d",&m); switch(m){case 1:puts("Month: January\nDays: 31");break;case 2:puts("Month: February\nDays: 28 or 29");break;case 3:puts("Month: March\nDays: 31");break;case 4:puts("Month: April\nDays: 30");break;case 5:puts("Month: May\nDays: 31");break;case 6:puts("Month: June\nDays: 30");break;case 7:puts("Month: July\nDays: 31");break;case 8:puts("Month: August\nDays: 31");break;case 9:puts("Month: September\nDays: 30");break;case 10:puts("Month: October\nDays: 31");break;case 11:puts("Month: November\nDays: 30");break;case 12:puts("Month: December\nDays: 31");break;default:puts("Error: Invalid month number! Please enter a number between 1 and 12.");} return 0;}
